1. using Microsoft.Extensions.ML;
2. using Microsoft.ML;
3. using TicketClassifier.Models;
4. using TicketClassifier.Services;
5. 
6. var builder = WebApplication.CreateBuilder(args);
7. 
8. // Train the model before building the host so the .zip file exists
9. var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
10. var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
11. TrainModel(dataPath, modelPath);
12. 
13. builder.Services.AddControllers();
14. builder.Services.AddSingleton<ModelTrainingService>();
15. builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
16.     .FromFile(modelPath);
17. 
18. var app = builder.Build();
19. app.MapControllers();
20. app.Run();
21. 
22. static void TrainModel(string dataPath, string modelPath)
23. {
24.     var mlContext = new MLContext(seed: 42);
25. 
26.     IDataView data = mlContext.Data.LoadFromTextFile<TicketInput>(
27.         dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
28. 
29.     var pipeline = mlContext.Transforms.Text
30.         .FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
31.         .Append(mlContext.Transforms.Text
32.             .FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
33.         .Append(mlContext.Transforms.Concatenate("Features",
34.             "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
35.         .Append(mlContext.Transforms.Conversion
36.             .MapValueToKey("Label", nameof(TicketInput.Category)))
37.         .Append(mlContext.MulticlassClassification.Trainers
38.             .SdcaMaximumEntropy("Label", "Features"))
39.         .Append(mlContext.Transforms.Conversion
40.             .MapKeyToValue("PredictedLabel"));
41. 
42.     var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
43.     var model = pipeline.Fit(split.TrainSet);
44. 
45.     var predictions = model.Transform(split.TestSet);
46.     var metrics = mlContext.MulticlassClassification.Evaluate(predictions);
47. 
48.     var logLossReduction = double.IsNaN(metrics.LogLossReduction) || double.IsInfinity(metrics.LogLossReduction)
49.         ? 0 : metrics.LogLossReduction;
50.     Console.WriteLine($"=== Model Evaluation Metrics ===");
51.     Console.WriteLine($"  MicroAccuracy:    {metrics.MicroAccuracy:F4}");
52.     Console.WriteLine($"  MacroAccuracy:    {metrics.MacroAccuracy:F4}");
53.     Console.WriteLine($"  LogLoss:          {metrics.LogLoss:F4}");
54.     Console.WriteLine($"  LogLossReduction: {logLossReduction:F4}");
55. 
56.     mlContext.Model.Save(model, data.Schema, modelPath);
57.     Console.WriteLine($"Model saved to {modelPath}");
58. }
59.

